// Структурные логи + единый correlation id на запрос
import { pinoHttp } from 'pino-http';
app.use(pinoHttp({
  genReqId: (req) => (req.headers['x-request-id'] as string) ?? randomUUID(),
  customProps: (req) => ({ userId: req.user?.id, tenantId: req.tenantId }),
  autoLogging: { ignore: (req) => req.url === '/health/live' },
}));

// RED-метрики (prom-client)
const httpDuration = new Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP latency',
  labelNames: ['method', 'route', 'status'] as const,
  buckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5],
});
// в интерсепторе: httpDuration.observe({ method, route, status }, (Date.now() - t0) / 1000)

// Алермы, на которые реально среагируют дежурные:
// - http_error_rate (5xx) > 1% (5 мин)
// - http_request p95 > SLA (например, 800 мс) (10 мин)
// - kafka_consumergroup_lag > 10 000 (5 мин)
// - process_resident_memory_bytes > лимита пода (15 мин)
// - процесс без heartbeat в k8s

// Очередь фоновых задач с изоляцией: одна плохая задача не вешает сервис
import { Queue, Worker } from 'bullmq';
export const emailQueue = new Queue('email', { connection, defaultJobOptions: {
  attempts: 5,
  backoff: { type: 'exponential', delay: 5_000 },   // + джиттер вручную
  removeOnComplete: { count: 1_000 },
  removeOnFail: { count: 5_000 },
}});

new Worker('email', async (job) => sendReceipt(job.data), {
  connection, concurrency: 10,                       // ограничиваем внешние вызовы
  limiter: { max: 100, duration: 1_000 },            // не долбить провайдера
});
